def should_stop(attempt, max_attempts, test_result, same_error_count):
    if test_result.get("passed"):
        return "success"
    if attempt >= max_attempts:
        return "max_attempts"
    if same_error_count >= 2:
        return "stuck"
    return None

def apply_mutations(source, mutations):
    result = []
    for old, new in mutations:
        if old not in source:
            continue
        result.append((source, source.replace(old, new, 1)))
    return result

