def reduce_summaries(summaries, group_size=3):
    if not summaries:
        return "", 0
    level = list(summaries)
    depth = 0
    while len(level) > 1:
        depth += 1
        new_level = []
        for i in range(0, len(level), group_size):
            group = level[i:i + group_size]
            new_level.append("；".join(group))
        level = new_level
    return level[0], depth

def verify_evidence(extraction, source_text):
    failed = []
    for field, data in extraction.items():
        evidence = data.get("evidence")
        if not evidence:
            failed.append(field)
            continue
        norm_src = "".join(source_text.split())
        norm_ev = "".join(evidence.split())
        if norm_ev not in norm_src:
            failed.append(field)
    return failed
